const svg=$('#mdp-svg'), out=$('#mdp-out');
const gSl=$('#mdp-gamma'), gL=$('#mdp-gamma-lbl'), pick=$('#mdp-action');
const W=640,H=320;
// Canonical 3-state MDP. States: 0=Start, 1=Wait, 2=Goal(absorbing).
// Actions per state: 'a' (advance) and 'b' (stay/idle).
const P={ 0:{a:[[1,1.0]], b:[[0,1.0]]},
          1:{a:[[2,0.8],[0,0.2]], b:[[1,1.0]]},
          2:{a:[[2,1.0]], b:[[2,1.0]]} };
const R={ 0:{a:0, b:0}, 1:{a:5, b:-1}, 2:{a:1, b:1} };
const names=['s0 Start','s1 Wait','s2 Goal'];
const pos=[[150,170],[370,170],[560,170]];
function render(){
  const g=+gSl.value; gL.textContent='γ = '+g.toFixed(2);
  const act=pick.value; // 'a' or 'b'
  svg.innerHTML='';
  // draw transition arrows for the chosen action, from each non-terminal state
  for(let s=0;s<3;s++){
    const outs=P[s][act];
    for(const [sp,p] of outs){
      if(sp===s){
        // self-loop drawn as a small arc above
        const [x,y]=pos[s];
        svg.appendChild(SVG('path',{d:`M${x-14} ${y-16} C ${x-40} ${y-70}, ${x+40} ${y-70}, ${x+14} ${y-16}`,
          fill:'none',stroke:'var(--cyan)','stroke-width':2,'marker-end':'url(#mdp-arrh)'}));
        const t=SVG('text',{x:x,y:y-58,'text-anchor':'middle','font-size':12,fill:'var(--cyan)'});
        t.textContent='p='+p.toFixed(2); svg.appendChild(t);
      } else {
        drawArrow(svg,pos[s],pos[sp],{color:'var(--cyan)',curve: sp<s?34:-18,markerId:'mdp-arrh',width:2,label:'p='+p.toFixed(2),labelSide: sp<s?0:1});
      }
    }
  }
  // nodes
  for(let s=0;s<3;s++){
    drawNode(svg,pos[s][0],pos[s][1], 's'+s, {r:22, fill:'var(--panel2)', stroke: s===2?'var(--green)':'var(--violet)'});
  }
  // reward labels under each node for this action
  for(let s=0;s<3;s++){
    const t=SVG('text',{x:pos[s][0],y:pos[s][1]+42,'text-anchor':'middle','font-size':12,fill:'var(--yellow)'});
    t.textContent='R(s'+s+','+act+') = '+R[s][act];
    svg.appendChild(t);
  }
  const rows=[];
  for(let s=0;s<3;s++){
    const outs=P[s][act].map(([sp,p])=>'P(s'+sp+'|s'+s+','+act+')='+p.toFixed(2)).join('  ');
    rows.push('s'+s+':  R='+R[s][act]+'    '+outs);
  }
  out.textContent =
    'action chosen at every state: '+(act==='a'?'a (advance)':'b (stay/idle)')+'    discount γ = '+g.toFixed(2)+'\n'+
    rows.join('\n')+'\n'+
    'each row is a probability distribution over next states: it sums to 1 ✓  (the Markov property: next state depends only on (s,a))';
}
ensureArrow(svg,'mdp-arrh','var(--cyan)');
gSl.addEventListener('input',render);
pick.addEventListener('change',render);
render();

const svg=$('#vf-svg'), out=$('#vf-out');
const gSl=$('#vf-gamma'), gL=$('#vf-gamma-lbl');
const p0=$('#vf-p0'), p1=$('#vf-p1');
const W=640,H=300;
const P={ 0:{a:[[1,1.0]], b:[[0,1.0]]},
          1:{a:[[2,0.8],[0,0.2]], b:[[1,1.0]]},
          2:{a:[[2,1.0]], b:[[2,1.0]]} };
const R={ 0:{a:0, b:0}, 1:{a:5, b:-1}, 2:{a:1, b:1} };
const pos=[[150,150],[370,150],[560,150]];
// deterministic policy pi: pi[s] in {'a','b'}; s2 forced to 'a' (only sensible action there)
function evalPolicy(pi,g){
  let V=[0,0,0];
  for(let it=0;it<2000;it++){
    const Vn=[0,0,0];
    for(let s=0;s<3;s++){ const act=pi[s]; let v=R[s][act]; for(const [sp,p] of P[s][act]) v+=g*p*V[sp]; Vn[s]=v; }
    let d=0; for(let s=0;s<3;s++) d=Math.max(d,Math.abs(Vn[s]-V[s]));
    V=Vn; if(d<1e-9) break;
  }
  return V;
}
function qOf(pi,V,g){ // Q^pi(s, action chosen) for display
  const Q={};
  for(let s=0;s<3;s++){ Q[s]={}; for(const act of ['a','b']){ let q=R[s][act]; for(const [sp,p] of P[s][act]) q+=g*p*V[sp]; Q[s][act]=q; } }
  return Q;
}
function render(){
  const g=+gSl.value; gL.textContent='γ = '+g.toFixed(2);
  const pi={0:p0.value,1:p1.value,2:'a'};
  const V=evalPolicy(pi,g);
  const Q=qOf(pi,V,g);
  svg.innerHTML='';
  for(let s=0;s<3;s++){ const act=pi[s];
    for(const [sp,p] of P[s][act]){
      if(sp===s){ const [x,y]=pos[s];
        svg.appendChild(SVG('path',{d:`M${x-14} ${y-16} C ${x-40} ${y-66}, ${x+40} ${y-66}, ${x+14} ${y-16}`,fill:'none',stroke:'var(--cyan)','stroke-width':2,'marker-end':'url(#vf-arrh)'}));
      } else {
        drawArrow(svg,pos[s],pos[sp],{color:'var(--cyan)',curve: sp<s?34:-18,markerId:'vf-arrh',width:2});
      }
    }
  }
  for(let s=0;s<3;s++){
    drawNode(svg,pos[s][0],pos[s][1], 's'+s, {r:22, fill:'var(--panel2)', stroke: s===2?'var(--green)':'var(--violet)'});
    const t=SVG('text',{x:pos[s][0],y:pos[s][1]+44,'text-anchor':'middle','font-size':13,fill:'var(--yellow)','font-weight':600});
    t.textContent='V='+V[s].toFixed(2); svg.appendChild(t);
    const t2=SVG('text',{x:pos[s][0],y:pos[s][1]-34,'text-anchor':'middle','font-size':12,fill:'var(--mute)'});
    t2.textContent='π(s'+s+')='+pi[s]; svg.appendChild(t2);
  }
  out.textContent =
    'policy  π: s0→'+pi[0]+'   s1→'+pi[1]+'   s2→a      γ = '+g.toFixed(2)+'\n'+
    'V^π  =  ( '+V.map(v=>v.toFixed(3)).join(',  ')+' )   — the unique solution of the Bellman expectation equations\n'+
    'check at s1:  V^π(s1) = R(s1,'+pi[1]+') + γ·Σ P·V = '+R[1][pi[1]]+' + '+g.toFixed(2)+'·(linear combo) = '+V[1].toFixed(3)+' ✓\n'+
    'Q^π(s1,a) = '+Q[1].a.toFixed(3)+'    Q^π(s1,b) = '+Q[1].b.toFixed(3)+'   (V^π(s1)=Q^π(s1,π(s1)) = '+Q[1][pi[1]].toFixed(3)+')';
}
ensureArrow(svg,'vf-arrh','var(--cyan)');
gSl.addEventListener('input',render);
p0.addEventListener('change',render);
p1.addEventListener('change',render);
render();

const svg=$('#opt-svg'), out=$('#opt-out');
const gSl=$('#opt-gamma'), gL=$('#opt-gamma-lbl');
const W=640,H=300;
const P={ 0:{a:[[1,1.0]], b:[[0,1.0]]},
          1:{a:[[2,0.8],[0,0.2]], b:[[1,1.0]]},
          2:{a:[[2,1.0]], b:[[2,1.0]]} };
const R={ 0:{a:0, b:0}, 1:{a:5, b:-1}, 2:{a:1, b:1} };
const pos=[[150,150],[370,150],[560,150]];
function optimal(g){
  let V=[0,0,0];
  for(let it=0;it<5000;it++){
    const Vn=[0,0,0];
    for(let s=0;s<3;s++){ let best=-1e18; for(const act of ['a','b']){ let q=R[s][act]; for(const [sp,p] of P[s][act]) q+=g*p*V[sp]; best=Math.max(best,q);} Vn[s]=best; }
    let d=0; for(let s=0;s<3;s++) d=Math.max(d,Math.abs(Vn[s]-V[s]));
    V=Vn; if(d<1e-10) break;
  }
  const Q={}, pol={};
  for(let s=0;s<3;s++){ Q[s]={}; for(const act of ['a','b']){ let q=R[s][act]; for(const [sp,p] of P[s][act]) q+=g*p*V[sp]; Q[s][act]=q; }
    pol[s]= Q[s].a>=Q[s].b ? 'a':'b'; }
  return {V,Q,pol};
}
function render(){
  const g=+gSl.value; gL.textContent='γ = '+g.toFixed(2);
  const {V,Q,pol}=optimal(g);
  svg.innerHTML='';
  // draw the GREEDY optimal action's transitions
  for(let s=0;s<3;s++){ const act=pol[s];
    for(const [sp,p] of P[s][act]){
      if(sp===s){ const [x,y]=pos[s];
        svg.appendChild(SVG('path',{d:`M${x-14} ${y-16} C ${x-40} ${y-66}, ${x+40} ${y-66}, ${x+14} ${y-16}`,fill:'none',stroke:'var(--green)','stroke-width':2.4,'marker-end':'url(#opt-arrh)'}));
      } else {
        drawArrow(svg,pos[s],pos[sp],{color:'var(--green)',curve: sp<s?34:-18,markerId:'opt-arrh',width:2.4});
      }
    }
  }
  for(let s=0;s<3;s++){
    drawNode(svg,pos[s][0],pos[s][1], 's'+s, {r:22, fill:'var(--panel2)', stroke: s===2?'var(--green)':'var(--violet)'});
    const t=SVG('text',{x:pos[s][0],y:pos[s][1]+44,'text-anchor':'middle','font-size':13,fill:'var(--yellow)','font-weight':600});
    t.textContent='V*='+V[s].toFixed(2); svg.appendChild(t);
    const t2=SVG('text',{x:pos[s][0],y:pos[s][1]-34,'text-anchor':'middle','font-size':12,fill:'var(--green)','font-weight':600});
    t2.textContent='π*(s'+s+')='+pol[s]; svg.appendChild(t2);
  }
  out.textContent =
    'γ = '+g.toFixed(2)+'\n'+
    'V*  =  ( '+V.map(v=>v.toFixed(3)).join(',  ')+' )      greedy optimal policy  π*: s0→'+pol[0]+'  s1→'+pol[1]+'  s2→'+pol[2]+'\n'+
    'Q*(s1,a) = '+Q[1].a.toFixed(3)+'   ≥   Q*(s1,b) = '+Q[1].b.toFixed(3)+'   ⇒  V*(s1)=max_a Q*(s1,a)='+Math.max(Q[1].a,Q[1].b).toFixed(3)+'\n'+
    'Q*(s0,a) = '+Q[0].a.toFixed(3)+'   vs   Q*(s0,b) = '+Q[0].b.toFixed(3)+'    (advancing beats idling: the max picks a)';
}
ensureArrow(svg,'opt-arrh','var(--green)');
gSl.addEventListener('input',render);
render();

const svg=$('#vi-svg'), out=$('#vi-out');
const gSl=$('#vi-gamma'), gL=$('#vi-gamma-lbl'), step=$('#vi-step'), reset=$('#vi-reset');
const W=640,H=300, padL=70, padR=30, padT=24, padB=46;
const P={ 0:{a:[[1,1.0]], b:[[0,1.0]]},
          1:{a:[[2,0.8],[0,0.2]], b:[[1,1.0]]},
          2:{a:[[2,1.0]], b:[[2,1.0]]} };
const R={ 0:{a:0, b:0}, 1:{a:5, b:-1}, 2:{a:1, b:1} };
function optimalV(g){
  let V=[0,0,0];
  for(let it=0;it<5000;it++){ const Vn=[0,0,0];
    for(let s=0;s<3;s++){ let best=-1e18; for(const act of ['a','b']){ let q=R[s][act]; for(const [sp,p] of P[s][act]) q+=g*p*V[sp]; best=Math.max(best,q);} Vn[s]=best; }
    let d=0; for(let s=0;s<3;s++) d=Math.max(d,Math.abs(Vn[s]-V[s])); V=Vn; if(d<1e-12) break; }
  return V;
}
function backup(V,g){ const Vn=[0,0,0];
  for(let s=0;s<3;s++){ let best=-1e18; for(const act of ['a','b']){ let q=R[s][act]; for(const [sp,p] of P[s][act]) q+=g*p*V[sp]; best=Math.max(best,q);} Vn[s]=best; }
  return Vn; }
let g=+gSl.value, Vk=[0,0,0], k=0, errs=[];
function err(V){ const Vs=optimalV(g); let d=0; for(let s=0;s<3;s++) d=Math.max(d,Math.abs(V[s]-Vs[s])); return d; }
function doReset(){ g=+gSl.value; Vk=[0,0,0]; k=0; errs=[err(Vk)]; render(); }
function render(){
  gL.textContent='γ = '+g.toFixed(2);
  svg.innerHTML='';
  // log-scale-ish error plot of ||V_k - V*||inf vs k, plus the gamma^k bound envelope
  const e0=errs[0]||1;
  const xs=(i)=> padL + (W-padL-padR)*(errs.length>1? i/(errs.length-1):0);
  const maxE=Math.max(e0,1e-9);
  const ys=(v)=> padT + (H-padT-padB)*(1 - v/maxE);
  // axes
  svg.appendChild(SVG('line',{x1:padL,y1:padT,x2:padL,y2:H-padB,stroke:'var(--line)','stroke-width':1}));
  svg.appendChild(SVG('line',{x1:padL,y1:H-padB,x2:W-padR,y2:H-padB,stroke:'var(--line)','stroke-width':1}));
  const yl=SVG('text',{x:padL-8,y:padT+4,'text-anchor':'end','font-size':11,fill:'var(--mute)'}); yl.textContent='‖V_k−V*‖∞'; svg.appendChild(yl);
  const xl=SVG('text',{x:W-padR,y:H-padB+18,'text-anchor':'end','font-size':11,fill:'var(--mute)'}); xl.textContent='iteration k'; svg.appendChild(xl);
  // gamma^k * e0 envelope (the contraction guarantee)
  let bound='';
  for(let i=0;i<errs.length;i++){ const v=e0*Math.pow(g,i); bound+=(i?' L':'M')+xs(i)+' '+ys(v); }
  if(errs.length>1) svg.appendChild(SVG('path',{d:bound,fill:'none',stroke:'var(--mute)','stroke-width':1.4,'stroke-dasharray':'5 4'}));
  // actual error curve
  let path='';
  for(let i=0;i<errs.length;i++){ path+=(i?' L':'M')+xs(i)+' '+ys(errs[i]); }
  if(errs.length>1) svg.appendChild(SVG('path',{d:path,fill:'none',stroke:'var(--yellow)','stroke-width':2.4}));
  for(let i=0;i<errs.length;i++) svg.appendChild(SVG('circle',{cx:xs(i),cy:ys(errs[i]),r:3.5,fill:'var(--yellow)'}));
  // legend
  const lg=SVG('text',{x:W-padR,y:padT+14,'text-anchor':'end','font-size':11,fill:'var(--yellow)'}); lg.textContent='actual error'; svg.appendChild(lg);
  const lg2=SVG('text',{x:W-padR,y:padT+30,'text-anchor':'end','font-size':11,fill:'var(--mute)'}); lg2.textContent='γ^k·error_0  bound'; svg.appendChild(lg2);
  const ratio = errs.length>=2 ? errs[errs.length-1]/errs[errs.length-2] : null;
  out.textContent =
    'γ = '+g.toFixed(2)+'    step k = '+k+'\n'+
    'V_'+k+' = ( '+Vk.map(v=>v.toFixed(3)).join(',  ')+' )      V* = ( '+optimalV(g).map(v=>v.toFixed(3)).join(',  ')+' )\n'+
    '‖V_'+k+' − V*‖∞ = '+errs[errs.length-1].toFixed(5)+(ratio!==null? ('     last ratio = '+ratio.toFixed(4)+'  ≤  γ = '+g.toFixed(2)+'  ✓'):'')+'\n'+
    'each Bellman-optimality backup contracts the sup-distance to V* by a factor ≤ γ; the dashed line is the γ^k guarantee';
}
step.addEventListener('click',()=>{ Vk=backup(Vk,g); k++; errs.push(err(Vk)); render(); });
reset.addEventListener('click',doReset);
gSl.addEventListener('input',()=>{ doReset(); });
doReset();

const N=3,gam=0.9,K=45;
const R=[[0,5,1],[0,-1,1]];
const P=[[[0,1,0],[0.2,0,0.8],[0,0,1]],[[1,0,0],[0,1,0],[0,0,1]]];
function bell(V){var nv=new Array(N);for(var s=0;s<N;s++){var best=-1e9;for(var a=0;a<2;a++){var q=R[a][s];for(var sp=0;sp<N;sp++)q+=gam*P[a][s][sp]*V[sp];if(q>best)best=q;}nv[s]=best;}return nv;}
var Vs=new Array(N).fill(0);for(var i=0;i<600;i++)Vs=bell(Vs);
const VK=[];var v=new Array(N).fill(0);VK.push(v.slice());for(var k=1;k<=K;k++){v=bell(v);VK.push(v.slice());}
var vmax=0;for(var s2=0;s2<N;s2++)if(Vs[s2]>vmax)vmax=Vs[s2];
const A=160,bw=160,base=300,H=(base-78)/(vmax||1);
const NAME=['s0','s1','s2 (goal)'];
function frame(t){
  while(G.firstChild)G.removeChild(G.firstChild);
  var k=Math.round(t*K);
  G.appendChild(SVG('line',{x1:80,y1:base,x2:560,y2:base,stroke:'var(--mute)','stroke-width':1,opacity:0.5}));
  G.appendChild(SVG('rect',{x:392,y:30,width:15,height:11,fill:'var(--cyan)','fill-opacity':0.45,stroke:'var(--cyan)','stroke-width':0.8}));
  var lk=SVG('text',{x:412,y:40,'font-size':12,fill:'var(--mute)'});lk.textContent='V_k';G.appendChild(lk);
  G.appendChild(SVG('line',{x1:452,y1:36,x2:474,y2:36,stroke:'var(--yellow)','stroke-width':2.5}));
  var ls=SVG('text',{x:480,y:40,'font-size':12,fill:'var(--mute)'});ls.textContent='V*';G.appendChild(ls);
  for(var s=0;s<N;s++){var x=A+s*bw;
    var hk=VK[k][s]*H; G.appendChild(SVG('rect',{x:x-34,y:base-hk,width:68,height:hk,fill:'var(--cyan)','fill-opacity':0.45,stroke:'var(--cyan)','stroke-width':0.8}));
    var yv=base-Vs[s]*H; G.appendChild(SVG('line',{x1:x-42,y1:yv,x2:x+42,y2:yv,stroke:'var(--yellow)','stroke-width':2.5}));
    var lab=SVG('text',{x:x,y:base+18,'font-size':12,fill:'var(--mute)','text-anchor':'middle'});lab.textContent=NAME[s];G.appendChild(lab);}
  var nm=0;for(var s3=0;s3<N;s3++){var dd=Math.abs(VK[k][s3]-Vs[s3]);if(dd>nm)nm=dd;}
  var prev=0;if(k>0){for(var s4=0;s4<N;s4++){var d2=Math.abs(VK[k-1][s4]-Vs[s4]);if(d2>prev)prev=d2;}}
  var ratio=(k>0&&prev>1e-9)?(nm/prev):0;
  out.innerHTML='sweep k = '+k+' / '+K+' &nbsp;\u00b7&nbsp; \u2016V<sub>k</sub> \u2212 V*\u2016\u221e = '+nm.toFixed(2)+(k>0?' &nbsp;\u00b7&nbsp; ratio = '+ratio.toFixed(2)+' (\u2264 \u03b3 = 0.90)':'');
}

const svg=$('#pi-svg'), out=$('#pi-out');
const gSl=$('#pi-gamma'), gL=$('#pi-gamma-lbl'), step=$('#pi-step'), reset=$('#pi-reset');
const W=640,H=270;
const P={ 0:{a:[[1,1.0]], b:[[0,1.0]]},
          1:{a:[[2,0.8],[0,0.2]], b:[[1,1.0]]},
          2:{a:[[2,1.0]], b:[[2,1.0]]} };
const R={ 0:{a:0, b:0}, 1:{a:5, b:-1}, 2:{a:1, b:1} };
const pos=[[150,120],[370,120],[560,120]];
let g=+gSl.value, pi={0:'b',1:'b',2:'a'}, V=[0,0,0], iter=0, stable=false;
function evalPolicy(p,gg){ let Vv=[0,0,0];
  for(let it=0;it<3000;it++){ const Vn=[0,0,0];
    for(let s=0;s<3;s++){ const act=p[s]; let v=R[s][act]; for(const [sp,q] of P[s][act]) v+=gg*q*Vv[sp]; Vn[s]=v; }
    let d=0; for(let s=0;s<3;s++) d=Math.max(d,Math.abs(Vn[s]-Vv[s])); Vv=Vn; if(d<1e-10) break; }
  return Vv; }
function greedy(Vv,gg){ const np={};
  for(let s=0;s<3;s++){ let qa=R[s].a,qb=R[s].b; for(const [sp,q] of P[s].a) qa+=gg*q*Vv[sp]; for(const [sp,q] of P[s].b) qb+=gg*q*Vv[sp]; np[s]= qa>=qb?'a':'b'; }
  return np; }
function doReset(){ g=+gSl.value; pi={0:'b',1:'b',2:'a'}; V=evalPolicy(pi,g); iter=0; stable=false; render(); }
function render(){
  gL.textContent='γ = '+g.toFixed(2);
  svg.innerHTML='';
  for(let s=0;s<3;s++){ const act=pi[s];
    for(const [sp,p] of P[s][act]){
      if(sp===s){ const [x,y]=pos[s];
        svg.appendChild(SVG('path',{d:`M${x-14} ${y-16} C ${x-40} ${y-64}, ${x+40} ${y-64}, ${x+14} ${y-16}`,fill:'none',stroke:'var(--pink)','stroke-width':2.2,'marker-end':'url(#pi-arrh)'}));
      } else { drawArrow(svg,pos[s],pos[sp],{color:'var(--pink)',curve: sp<s?34:-18,markerId:'pi-arrh',width:2.2}); }
    }
  }
  for(let s=0;s<3;s++){
    drawNode(svg,pos[s][0],pos[s][1], 's'+s, {r:22, fill:'var(--panel2)', stroke: s===2?'var(--green)':'var(--violet)'});
    const t=SVG('text',{x:pos[s][0],y:pos[s][1]+44,'text-anchor':'middle','font-size':13,fill:'var(--yellow)','font-weight':600}); t.textContent='V='+V[s].toFixed(2); svg.appendChild(t);
    const t2=SVG('text',{x:pos[s][0],y:pos[s][1]-34,'text-anchor':'middle','font-size':12,fill:'var(--pink)','font-weight':600}); t2.textContent='π(s'+s+')='+pi[s]; svg.appendChild(t2);
  }
  out.textContent =
    'γ = '+g.toFixed(2)+'    policy-iteration round = '+iter+'\n'+
    'current policy  π: s0→'+pi[0]+'  s1→'+pi[1]+'  s2→'+pi[2]+'\n'+
    'V^π (exact policy-evaluation solve) = ( '+V.map(v=>v.toFixed(3)).join(',  ')+' )\n'+
    (stable? 'policy is STABLE — greedy(V^π) = π, so π = π* is optimal. Converged in finitely many rounds ✓'
           : 'press “evaluate + improve”: solve V^π, then set π ← greedy(V^π). Monotone improvement, finite #policies ⇒ finite convergence.');
}
step.addEventListener('click',()=>{ if(stable) return;
  V=evalPolicy(pi,g);
  const np=greedy(V,g);
  let same=true; for(let s=0;s<3;s++) if(np[s]!==pi[s]) same=false;
  pi=np; iter++; if(same){ stable=true; } render(); });
reset.addEventListener('click',doReset);
gSl.addEventListener('input',doReset);
doReset();

const svg=$('#hz-svg'), out=$('#hz-out');
const gSl=$('#hz-gamma'), gL=$('#hz-gamma-lbl');
const W=640,H=300, padL=58, padR=24, padT=22, padB=44;
function render(){
  const g=+gSl.value; gL.textContent='γ = '+g.toFixed(3);
  svg.innerHTML='';
  // plot discount weights gamma^t for t=0..T and shade the effective horizon 1/(1-g)
  const T=40;
  const xs=(t)=> padL + (W-padL-padR)*(t/T);
  const ys=(w)=> padT + (H-padT-padB)*(1-w); // weight in [0,1]
  svg.appendChild(SVG('line',{x1:padL,y1:padT,x2:padL,y2:H-padB,stroke:'var(--line)','stroke-width':1}));
  svg.appendChild(SVG('line',{x1:padL,y1:H-padB,x2:W-padR,y2:H-padB,stroke:'var(--line)','stroke-width':1}));
  const yl=SVG('text',{x:padL-8,y:padT+4,'text-anchor':'end','font-size':11,fill:'var(--mute)'}); yl.textContent='weight γ^t'; svg.appendChild(yl);
  const xl=SVG('text',{x:W-padR,y:H-padB+18,'text-anchor':'end','font-size':11,fill:'var(--mute)'}); xl.textContent='time step t'; svg.appendChild(xl);
  // effective horizon marker
  const Heff=1/(1-g);
  if(Heff<=T){ const x=xs(Heff);
    svg.appendChild(SVG('line',{x1:x,y1:padT,x2:x,y2:H-padB,stroke:'var(--green)','stroke-width':1.4,'stroke-dasharray':'5 4'}));
    const tt=SVG('text',{x:x+5,y:padT+14,'text-anchor':'start','font-size':11,fill:'var(--green)'}); tt.textContent='1/(1−γ) ≈ '+Heff.toFixed(1); svg.appendChild(tt);
  }
  let path='';
  for(let t=0;t<=T;t++){ const w=Math.pow(g,t); path+=(t?' L':'M')+xs(t)+' '+ys(w); }
  svg.appendChild(SVG('path',{d:path,fill:'none',stroke:'var(--yellow)','stroke-width':2.4}));
  // a half-life style reference: weight at t=Heff is g^(1/(1-g)) -> ~ 1/e
  const wHeff=Math.pow(g,Heff);
  const Hf=1/(1-g);
  out.textContent =
    'γ = '+g.toFixed(3)+'\n'+
    'effective horizon  ≈  1/(1−γ)  =  '+Hf.toFixed(2)+' steps   (rewards beyond a few of these contribute almost nothing)\n'+
    'weight on the reward at t = 1/(1−γ) is γ^{1/(1−γ)} ≈ '+wHeff.toFixed(3)+'  →  about 1/e ≈ 0.368 as γ→1\n'+
    'finite-horizon: sum the first N rewards (no discount needed, but the optimal policy becomes time-dependent).\n'+
    'average-reward: the γ→1 limit, optimize lim (1/N)Σ R_t — the per-step gain, used when no discounting is natural.';
}
gSl.addEventListener('input',render);
render();
